app.post('/api/users',authLimiter, async (req,res)=>{const email=cleanEmail(req.body.email),fullName=String(req.body.fullName||'').trim(),password=req.body.password;if(!emailPattern.test(email))return res.status(400).json({success:false,msg:'Email không hợp lệ.'});if(fullName.length<2||fullName.length>80)return res.status(400).json({success:false,msg:'Họ tên phải từ 2 đến 80 ký tự.'});if(!validPassword(password))return res.status(400).json({success:false,msg:'Mật khẩu phải dài từ 8 đến 72 ký tự.'});if(!['mentee','mentor'].includes(req.body.role||'mentee'))return res.status(400).json({success:false,msg:'Vai trò đăng ký không hợp lệ.'});if(await User.exists({email}))return res.status(409).json({success:false,msg:'Email/Tài khoản này đã tồn tại!'});const user=await User.create({...req.body,email,fullName,password:await bcrypt.hash(password,PASSWORD_HASH_ROUNDS),role:req.body.role||'mentee'});res.status(201).json({success:true,msg:'Đăng ký thành công!',user:toClient(user)});});
app.post('/api/auth/email-verification/send', async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!user) return res.status(404).json({ success: false, msg: 'Không tìm thấy tài khoản với email này.' }); try { await issueOtp(user, 'verify-email'); res.json({ success: true, msg: 'Mã OTP đã được gửi tới email của bạn.' }); } catch (error) { res.status(503).json({ success: false, msg: error.message }); } });
app.post('/api/auth/email-verification/verify', async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!validateOtp(user, 'verify-email', req.body.code)) return res.status(400).json({ success: false, msg: 'Mã OTP không đúng hoặc đã hết hạn.' }); user.emailVerified = true; user.otpHash = undefined; user.otpPurpose = undefined; user.otpExpiresAt = undefined; await user.save(); res.json({ success: true, msg: 'Email đã được xác minh.' }); });
app.post('/api/auth/password-reset/send', async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!user) return res.status(404).json({ success: false, msg: 'Email này chưa có tài khoản PSIFU.' }); try { await issueOtp(user, 'password-reset'); res.json({ success: true, msg: 'Mã đặt lại mật khẩu đã được gửi.' }); } catch (error) { console.error('Password-reset OTP delivery failed:', error.message); res.status(503).json({ success: false, msg: error.message }); } });
app.post('/api/auth/password-reset/verify', async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!validateOtp(user, 'password-reset', req.body.code)) return res.status(400).json({ success: false, msg: 'Mã OTP không đúng hoặc đã hết hạn.' }); res.json({ success: true }); });
app.post('/api/auth/password-reset/complete', authLimiter, async (req,res)=>{const user=await User.findOne({email:cleanEmail(req.body.email)});if(!validPassword(req.body.password))return res.status(400).json({success:false,msg:'Mật khẩu phải dài từ 8 đến 72 ký tự.'});if(!validateOtp(user,'password-reset',req.body.code))return res.status(400).json({success:false,msg:'Mã OTP không đúng hoặc đã hết hạn.'});user.password=await bcrypt.hash(req.body.password,PASSWORD_HASH_ROUNDS);user.otpHash=undefined;user.otpPurpose=undefined;user.otpExpiresAt=undefined;await user.save();res.json({success:true,msg:'Đặt lại mật khẩu thành công.'});});
app.post('/api/auth/login', authLimiter, async (req, res) => {
  const email = req.body.email?.trim().toLowerCase();
  const user = await User.findOne({ email });
  if (!user) return res.status(404).json({ success: false, code: 'EMAIL_NOT_FOUND', msg: 'Email này chưa có tài khoản PSIFU.' });
  const passwordOk=await bcrypt.compare(String(req.body.password||''),user.password).catch(()=>false); const legacyPasswordOk=!passwordOk&&user.password===req.body.password;
  if (!passwordOk&&!legacyPasswordOk) return res.status(401).json({ success: false, code: 'WRONG_PASSWORD', msg: 'Mật khẩu chưa chính xác. Vui lòng thử lại.' });
  res.json({ success: true, user: toClient(user), accessToken:makeToken(user) });
  if(legacyPasswordOk||bcrypt.getRounds(user.password)>PASSWORD_HASH_ROUNDS){bcrypt.hash(req.body.password,PASSWORD_HASH_ROUNDS).then(password=>User.updateOne({_id:user._id},{$set:{password}})).catch(()=>{});}
});
app.post('/api/auth/google', authLimiter, async (req, res) => {
  const idToken = String(req.body.idToken || '');
  const clientId = process.env.GOOGLE_WEB_CLIENT_ID;
  if (!clientId) return res.status(503).json({ success: false, msg: 'Đăng nhập Google chưa được cấu hình trên máy chủ.' });
  if (!idToken || idToken.length > 4096) return res.status(400).json({ success: false, msg: 'Google ID token không hợp lệ.' });
  try {
    const response = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(idToken)}`);
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.aud !== clientId || !['accounts.google.com', 'https://accounts.google.com'].includes(payload.iss) || !['true', true].includes(payload.email_verified) || !emailPattern.test(payload.email || '') || !payload.sub) {
      return res.status(401).json({ success: false, msg: 'Không thể xác minh tài khoản Google này.' });
    }
    const email = cleanEmail(payload.email);
    let user = await User.findOne({ $or: [{ googleSubject: payload.sub }, { email }] });
    if (user && user.googleSubject && user.googleSubject !== payload.sub) return res.status(409).json({ success: false, msg: 'Email này đã được liên kết với một tài khoản Google khác.' });
    if (!user) {
      const fullName = String(payload.name || email.split('@')[0]).trim().slice(0, 80) || 'PSIFU Member';
      user = await User.create({ fullName, email, password: await bcrypt.hash(crypto.randomBytes(32).toString('hex'), PASSWORD_HASH_ROUNDS), googleSubject: payload.sub, avatarUrl: payload.picture || '', emailVerified: true, role: 'mentee', isFirstLogin: true });
    } else {
      user.googleSubject = payload.sub;
      user.emailVerified = true;
      if (!user.avatarUrl && payload.picture) user.avatarUrl = payload.picture;
      await user.save();
    }
    res.json({ success: true, user: toClient(user), accessToken: makeToken(user) });
  } catch (error) {
    console.error('Google sign-in verification:', error.message);
    res.status(502).json({ success: false, msg: 'Không thể xác minh Google lúc này. Vui lòng thử lại.' });
  }
});
app.patch('/api/users/:email',requireAuth,requireSelfOrAdmin(), async (req,res)=>{const allowed=['fullName','avatarUrl','university','academicYear','fptK','studentId','major','specialization','track','currentTerm','mentorBio','mentorFee','mentorCourses','mentorAvailability','notificationPreferences','isFirstLogin'];const updates={};for(const key of allowed)if(req.body[key]!==undefined)updates[key]=req.body[key];if(updates.fullName!==undefined&&(String(updates.fullName).trim().length<2||String(updates.fullName).trim().length>80))return res.status(400).json({success:false,msg:'Họ tên phải từ 2 đến 80 ký tự.'});if(updates.mentorFee!==undefined&&(!Number.isInteger(Number(updates.mentorFee))||updates.mentorFee<0||updates.mentorFee>10000))return res.status(400).json({success:false,msg:'Mức phí Mentor không hợp lệ.'});const user=await User.findOneAndUpdate({email:req.params.email.toLowerCase()},{$set:updates},{new:true});if(!user)return res.status(404).json({success:false});res.json({success:true,user:toClient(user)});});
app.get('/api/users/:email/settings', async (req,res) => { const user=await User.findOne({email:req.params.email.toLowerCase()}); if(!user)return res.status(404).json({success:false}); res.json({notificationPreferences:user.notificationPreferences||{},mentorAvailability:user.mentorAvailability||{accepting:true,slots:[]}}); });
app.patch('/api/users/:email/settings',requireAuth,requireSelfOrAdmin(),async(req,res)=>{const allowed={};if(req.body.notificationPreferences&&typeof req.body.notificationPreferences==='object')allowed.notificationPreferences=req.body.notificationPreferences;if(req.body.mentorAvailability&&typeof req.body.mentorAvailability==='object')allowed.mentorAvailability=req.body.mentorAvailability;const user=await User.findOneAndUpdate({email:req.params.email.toLowerCase()},{$set:allowed},{new:true});if(!user)return res.status(404).json({success:false});res.json({success:true,notificationPreferences:user.notificationPreferences,mentorAvailability:user.mentorAvailability});});
app.post('/api/uploads/cloudinary-signature',async(req,res)=>{const email=req.body.email?.trim().toLowerCase();const user=await User.findOne({email});if(!user||user.role!=='mentor')return res.status(403).json({success:false,msg:'Chỉ Mentor được tải tài liệu lên.'});if(!cloudinaryConfigured())return res.status(503).json({success:false,msg:'Cloudinary chưa được cấu hình trên máy chủ.'});const fileName=String(req.body.fileName||'document.pdf');if(!fileName.toLowerCase().endsWith('.pdf'))return res.status(400).json({success:false,msg:'PSIFU chỉ hỗ trợ tệp PDF.'});const timestamp=Math.floor(Date.now()/1000);const safeEmail=email.replace(/[^a-z0-9]/gi,'_');const params={folder:`psifu/mentor-documents/${safeEmail}`,public_id:`doc_${timestamp}_${crypto.randomUUID().slice(0,8)}`,timestamp};res.json({success:true,cloudName:process.env.CLOUDINARY_CLOUD_NAME,apiKey:process.env.CLOUDINARY_API_KEY,timestamp,folder:params.folder,publicId:params.public_id,signature:cloudinarySignature(params)});});
app.post('/api/payments/payos/topups', async (req,res) => { const email=req.body.email?.trim().toLowerCase(); const coins=Number(req.body.coins); const packages=[50,100,200,500]; if(!email || !packages.includes(coins)) return res.status(400).json({success:false,msg:'Gói nạp không hợp lệ.'}); if(!payosConfigured()) return res.status(503).json({success:false,msg:'PayOS chưa được cấu hình trên máy chủ. Hãy thêm PAYOS_CLIENT_ID, PAYOS_API_KEY, PAYOS_CHECKSUM_KEY, PAYOS_RETURN_URL và PAYOS_CANCEL_URL.'}); const user=await User.findOne({email}); if(!user) return res.status(404).json({success:false,msg:'Không tìm thấy tài khoản.'}); try { const orderCode=await nextPayosOrderCode(); const amount=coins*1000; const requestData={orderCode,amount,description:`PSIFU ${coins} Xu`,returnUrl:process.env.PAYOS_RETURN_URL,cancelUrl:process.env.PAYOS_CANCEL_URL,items:[{name:`PSIFU ${coins} Xu`,quantity:1,price:amount}]}; requestData.signature=payosSignature({orderCode,amount,description:requestData.description,returnUrl:requestData.returnUrl,cancelUrl:requestData.cancelUrl}); const payment=await payosRequest('/v2/payment-requests',{method:'POST',body:JSON.stringify(requestData)}); const order=await PaymentOrder.create({orderCode,userEmail:email,coins,amount,paymentLinkId:payment.paymentLinkId,checkoutUrl:payment.checkoutUrl}); res.status(201).json({success:true,orderCode:order.orderCode,checkoutUrl:order.checkoutUrl,qrCode:payment.qrCode,amount:order.amount,status:order.status}); } catch(error){ console.error('PayOS create payment link:',error.message); res.status(502).json({success:false,msg:error.message||'Không thể tạo liên kết PayOS.'}); } });
app.get('/api/payments/payos/orders/:orderCode', async (req,res) => { const order=await PaymentOrder.findOne({orderCode:Number(req.params.orderCode)}); if(!order) return res.status(404).json({success:false,msg:'Không tìm thấy đơn thanh toán.'}); res.json({success:true,orderCode:order.orderCode,status:order.status,coins:order.coins,amount:order.amount,userXu:order.status==='PAID'?(await User.findOne({email:order.userEmail}).select('userXu'))?.userXu:undefined}); });
app.post('/api/payments/payos/webhook', async (req,res) => { try { const payload=req.body||{}; const expected=payosSignature(payload.data||{}); const received=String(payload.signature||''); if(!received || expected.length!==received.length || !crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(received))) return res.status(400).json({success:false,msg:'Webhook signature không hợp lệ.'}); if(payload.code!=='00' || payload.success!==true || payload.data?.code!=='00') return res.status(200).json({success:true,ignored:true}); const existing=await PaymentOrder.findOne({orderCode:Number(payload.data.orderCode)}); if(!existing || existing.status==='PAID') return res.status(200).json({success:true,ignored:true}); if(existing.amount!==Number(payload.data.amount)) return res.status(400).json({success:false,msg:'Số tiền webhook không khớp đơn hàng.'}); const order=await PaymentOrder.findOneAndUpdate({orderCode:existing.orderCode,status:'PENDING'},{$set:{status:'PAID',reference:payload.data.reference,paidAt:new Date()}},{new:true}); if(!order) return res.status(200).json({success:true,ignored:true}); const user=await User.findOneAndUpdate({email:order.userEmail},{$inc:{userXu:order.coins}},{new:true}); if(!user) return res.status(404).json({success:false}); await Transaction.create({userEmail:user.email,type:'PAYOS_TOPUP',amount:order.coins,status:'SUCCESS',metadata:{orderCode:order.orderCode,amountVnd:order.amount,reference:order.reference}}); await Notification.create({userEmail:user.email,title:'Nạp Xu thành công',body:`PayOS đã xác nhận đơn #${order.orderCode}. ${order.coins} Xu đã được cộng vào ví.`,type:'WALLET'}); res.status(200).json({success:true}); } catch(error){ console.error('PayOS webhook:',error.message); res.status(500).json({success:false,msg:'Không thể xử lý webhook.'}); } });
app.put('/api/mentors/:email/bank-account',async(req,res)=>{const email=req.params.email.trim().toLowerCase(),bank=req.body.bankAccount||{};const required=['bankName','accountNumber','accountHolder'];if(required.some(key=>!String(bank[key]||'').trim()))return res.status(400).json({success:false,msg:'Hãy nhập đủ ngân hàng, số tài khoản và tên chủ tài khoản.'});if(!/^\d{6,19}$/.test(String(bank.accountNumber)))return res.status(400).json({success:false,msg:'Số tài khoản phải gồm 6–19 chữ số.'});const user=await User.findOneAndUpdate({email,role:'mentor'},{$set:{bankAccount:{bankName:String(bank.bankName).trim(),accountNumber:String(bank.accountNumber).trim(),accountHolder:String(bank.accountHolder).trim().toUpperCase(),bin:String(bank.bin||'').trim()}}},{new:true});if(!user)return res.status(404).json({success:false,msg:'Không tìm thấy tài khoản Mentor.'});res.json({success:true,bankAccount:user.bankAccount});});
app.post('/api/payouts',async(req,res)=>{const email=req.body.email?.trim().toLowerCase(),amountXu=Number(req.body.amountXu);if(!email||!Number.isInteger(amountXu)||amountXu<50)return res.status(400).json({success:false,msg:'Số Xu rút tối thiểu là 50 Xu.'});const user=await User.findOneAndUpdate({email,role:'mentor',availableXu:{$gte:amountXu},'bankAccount.accountNumber':{$exists:true,$ne:''}},{$inc:{availableXu:-amountXu}},{new:true});if(!user)return res.status(400).json({success:false,msg:'Số dư khả dụng không đủ hoặc bạn chưa thêm tài khoản ngân hàng.'});try{const payoutCode=`PO-${Date.now()}-${crypto.randomUUID().slice(0,6).toUpperCase()}`;const payout=await Payout.create({payoutCode,mentorEmail:email,amountXu,amountVnd:amountXu*1000,bankAccount:user.bankAccount,status:'PROCESSING'});await Transaction.create({userEmail:email,type:'MENTOR_PAYOUT',amount:-amountXu,status:'PROCESSING',metadata:{payoutCode,bankName:user.bankAccount.bankName,accountNumber:user.bankAccount.accountNumber}});await Notification.create({userEmail:email,title:'Yêu cầu rút Xu đang xử lý',body:`Lệnh ${payoutCode} rút ${amountXu} Xu đang chờ đối soát.`,type:'WALLET'});res.status(201).json({success:true,payout:toClient(payout),availableXu:user.availableXu});}catch(error){await User.findOneAndUpdate({email},{$inc:{availableXu:amountXu}});throw error;}});
