app.get('/api/premium/plan',(_req,res)=>res.json(PREMIUM_PLAN));
app.get('/api/premium/subscription/:email',async(req,res)=>{const user=await User.findOne({email:req.params.email.toLowerCase()});if(!user)return res.status(404).json({success:false});res.json(subscriptionState(user));});
app.post('/api/premium/mock-payment/complete',async(req,res)=>{const user=await User.findOne({email:req.body.email?.toLowerCase()});if(!user)return res.status(404).json({success:false});const startedAt=new Date();const expiresAt=new Date(startedAt.getTime()+PREMIUM_PLAN.durationDays*86400000);user.subscription={plan:'PREMIUM',status:'ACTIVE',startedAt,expiresAt};await user.save();await Transaction.create({userEmail:user.email,type:'PREMIUM_SUBSCRIPTION',amount:PREMIUM_PLAN.price,status:'SUCCESS',metadata:{mode:'VNPAY_MOCK'}});await Notification.create({userEmail:user.email,title:'Chào mừng đến PSIFU Premium!',body:'Premium của bạn đã được kích hoạt.',type:'PREMIUM'});res.json({success:true,subscription:subscriptionState(user)});});
app.get('/api/premium/documents/:email',async(req,res)=>{const user=await User.findOne({email:req.params.email.toLowerCase()});if(!isPremiumUser(user))return res.status(403).json({success:false,code:'PREMIUM_REQUIRED',message:'Tài nguyên này cần PSIFU Premium.'});res.json((await PremiumDocument.find()).map(toClient));});
app.post('/api/quiz/access',async(req,res)=>{const user=await User.findOne({email:req.body.email?.toLowerCase()});if(!user)return res.status(404).json({success:false});const period=new Date().toISOString().slice(0,7);if(user.aiQuizUsagePeriod!==period){user.aiQuizUsagePeriod=period;user.aiQuizUsage=0;}const limit=isPremiumUser(user)?PREMIUM_PLAN.premiumAiQuizLimit:PREMIUM_PLAN.freeAiQuizLimit;if(user.aiQuizUsage>=limit){await user.save();return res.status(429).json({success:false,code:isPremiumUser(user)?'LIMIT_REACHED':'PREMIUM_REQUIRED',limit});}user.aiQuizUsage+=1;await user.save();res.json({success:true,remaining:limit-user.aiQuizUsage,plan:subscriptionState(user).plan});});
app.get('/api/notifications/:email',async(req,res)=>res.json((await Notification.find({userEmail:req.params.email.toLowerCase()}).sort({createdAt:-1}).limit(30)).map(toClient)));
app.patch('/api/notifications/:id/read',async(req,res)=>res.json({success:!!await Notification.findByIdAndUpdate(req.params.id,{read:true})}));
app.get('/api/questions', async (_req, res) => res.json((await Question.find().sort({ createdAt: -1 })).map(toClient)));
app.post('/api/questions', async (req, res) => res.status(201).json(toClient(await Question.create(req.body))));
app.get('/api/bookings', async (_req, res) => res.json((await Booking.find().sort({ createdAt: -1 })).map(toClient)));
app.post('/api/bookings', async (req, res) => { if (await Booking.exists({ mentorEmail: req.body.mentorEmail, dateTime: req.body.dateTime })) return res.status(409).json({ success: false, msg: 'Khung giờ này đã có mentee đặt trước.' }); res.status(201).json(toClient(await Booking.create({ ...req.body, meetingLink: req.body.meetingLink || 'https://meet.google.com/psifu-session' }))); });
app.patch('/api/bookings/:id', async (req, res) => res.json({ success: !!await Booking.findByIdAndUpdate(req.params.id, req.body) }));
app.get('/api/chats/:roomId', async (req, res) => res.json((await ChatMessage.find({ roomId: req.params.roomId }).sort({ createdAt: 1 }).limit(25)).map(toClient)));
app.post('/api/chats/:roomId', async (req, res) => res.status(201).json(toClient(await ChatMessage.create({ ...req.body, roomId: req.params.roomId }))));
const catalogDocument = doc => { const item=toClient(doc); delete item.fileUri; delete item.cloudinaryPublicId; return item; };
app.get('/api/mentor-documents', async (req, res) => { const filter={}; if(req.query.status)filter.status=req.query.status; if(req.query.mentorEmail)filter.mentorEmail=req.query.mentorEmail.toLowerCase(); const documents=await MentorDocument.find(filter).sort({createdAt:-1}); res.json((req.query.catalog==='true'?documents.map(catalogDocument):documents.map(toClient))); });
app.post('/api/mentor-documents', async (req, res) => res.status(201).json(toClient(await MentorDocument.create(req.body))));
app.get('/api/document-unlocks/:email',async(req,res)=>{const unlocks=await DocumentUnlock.find({userEmail:req.params.email.toLowerCase()}).select('documentId');res.json(unlocks.map(item=>String(item.documentId)));});
app.post('/api/mentor-documents/:id/unlock',async(req,res)=>{const email=req.body.email?.trim().toLowerCase();const document=await MentorDocument.findOne({_id:req.params.id,status:'PUBLISHED'});if(!email||!document)return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu đã xuất bản.'});const exists=await DocumentUnlock.exists({userEmail:email,documentId:document._id});if(exists)return res.json({success:true,alreadyUnlocked:true,userXu:(await User.findOne({email}).select('userXu'))?.userXu});const fee=Number(document.fee||0);const user=await User.findOneAndUpdate({email,userXu:{$gte:fee}},{$inc:{userXu:-fee}},{new:true});if(!user)return res.status(400).json({success:false,msg:'Bạn không đủ Xu để mở khóa tài liệu.'});try{await DocumentUnlock.create({userEmail:email,documentId:document._id});await MentorDocument.findByIdAndUpdate(document._id,{$inc:{unlocks:1,revenue:fee}});await Transaction.create({userEmail:email,type:'DOCUMENT_UNLOCK',amount:-fee,status:'SUCCESS',metadata:{documentId:String(document._id),title:document.title}});res.status(201).json({success:true,userXu:user.userXu});}catch(error){await User.findOneAndUpdate({email},{$inc:{userXu:fee}});if(error?.code===11000)return res.json({success:true,alreadyUnlocked:true,userXu:(await User.findOne({email}).select('userXu'))?.userXu});throw error;}});
app.get('/api/mentor-documents/:id/access',async(req,res)=>{const email=req.query.email?.trim().toLowerCase();const document=await MentorDocument.findOne({_id:req.params.id,status:'PUBLISHED'});if(!email||!document)return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu.'});const unlocked=Number(document.fee||0)===0||await DocumentUnlock.exists({userEmail:email,documentId:document._id});if(!unlocked)return res.status(403).json({success:false,msg:'Hãy mở khóa tài liệu trước.'});res.json({success:true,document:{...catalogDocument(document),fileUri:document.fileUri}});});
app.use((err, _req, res, _next) => { console.error(err); res.status(500).json({ success: false, msg: 'Lỗi máy chủ.' }); });
const port = process.env.PORT || 4000;
mongoose.connect(process.env.MONGODB_URI).then(async () => { await User.bulkWrite(systemUsers.map(user => ({ updateOne: { filter: { email: user.email }, update: { $setOnInsert: user }, upsert: true } }))); await Course.collection.dropIndex('code_1').catch(() => null); await Course.collection.dropIndex('code_1_major_1_specialization_1').catch(() => null); await Course.collection.createIndex({ code: 1, major: 1, specialization: 1, track: 1 }, { unique: true }); await Course.bulkWrite(allCourseSeeds.map(course => ({ updateOne: { filter: { code: course.code, major: course.major, specialization: course.specialization, track: course.track }, update: { $set: course }, upsert: true } }))); app.listen(port, '0.0.0.0', () => console.log(`PSIFU API is running on port ${port}`)); }).catch(error => { console.error('Không thể kết nối MongoDB:', error.message); process.exit(1); });
